<template><view class="page"><view class="filters"><picker :range="priorities" range-key="label" @change="changePriority"><view class="filter">{{ priorityLabel }}⌄</view></picker><picker mode="date" :value="date" @change="changeDate"><view class="filter">{{ date || '选择日期' }}⌄</view></picker><button class="clear" size="mini" @click="clearFilters">清除</button></view><view class="list"><view v-for="item in items" :key="item.id||item.alarmTime" class="card alarm" @click="open(item)"><view class="card__top"><text class="card__title">{{ item.alarmDescription||alarmType(item) }}</text><text class="priority" :class="priorityClass(item.alarmPriority)">{{ priorityText(item.alarmPriority) }}</text></view><text class="card__meta">设备：{{item.deviceId||'-'}}\n通道：{{item.channelId||'-'}}\n时间：{{item.alarmTime||'-'}}</text></view><EmptyState v-if="!loading&&!items.length" title="暂无告警" description="当前筛选条件下没有告警记录"/><view v-if="items.length" class="footer">{{loading?'加载中…':finished?'没有更多了':'上拉加载更多'}}</view></view></view></template>
<script setup lang="ts">
import{computed,ref}from'vue';import{onPullDownRefresh,onReachBottom,onShow}from'@dcloudio/uni-app';import EmptyState from'@/components/EmptyState.vue';import{queryAlarms,type AlarmItem}from'@/api/alarm';import{showRequestError}from'@/utils/request';import{useAuthStore}from'@/stores/auth'
const auth=useAuthStore(),items=ref<AlarmItem[]>([]),page=ref(1),loading=ref(false),finished=ref(false),priority=ref(''),date=ref('');const priorities=[{label:'全部等级',value:''},{label:'一级告警',value:'1'},{label:'二级告警',value:'2'},{label:'三级告警',value:'3'},{label:'四级告警',value:'4'}];const priorityLabel=computed(()=>priorities.find(i=>i.value===priority.value)?.label||'全部等级')
function range(day:string,end=false){return day?`${day} ${end?'23:59:59':'00:00:00'}`:''}async function load(reset=false){if(loading.value||(!reset&&finished.value))return;if(reset){page.value=1;finished.value=false}loading.value=true;try{const r=await queryAlarms({page:page.value,count:20,alarmPriority:priority.value,startTime:range(date.value),endTime:range(date.value,true)});const list=r.list||r.items||[];items.value=reset?list:[...items.value,...list];finished.value=list.length<20;page.value++}catch(e){showRequestError(e)}finally{loading.value=false;uni.stopPullDownRefresh()}}
function changePriority(e:any){priority.value=priorities[Number(e.detail.value)].value;load(true)}function changeDate(e:any){date.value=e.detail.value;load(true)}function clearFilters(){priority.value='';date.value='';load(true)}function alarmType(i:AlarmItem){return i.alarmType?`告警类型 ${i.alarmType}`:'设备告警'}function priorityText(v?:string){return v?`${v}级`:'告警'}function priorityClass(v?:string){return v==='1'?'critical':v==='2'?'high':'normal'}
function open(i:AlarmItem){if(i.id)uni.navigateTo({url:`/pages/alarm/detail?id=${i.id}`})}onShow(()=>{if(auth.requireAuth()&&!items.value.length)load(true)});onPullDownRefresh(()=>load(true));onReachBottom(()=>load())
</script><style lang="scss" scoped>@use '@/styles/list.scss';.filters{display:flex;align-items:center;gap:14rpx;padding:18rpx 24rpx;background:#fff}.filter{padding:16rpx 22rpx;background:#f2f4f8;border-radius:16rpx;font-size:24rpx}.clear{margin:0 0 0 auto;color:#2368f2;background:#eef4ff}.priority{padding:6rpx 14rpx;border-radius:999rpx;font-size:21rpx}.critical{color:#b42318;background:#fee4e2}.high{color:#b54708;background:#ffead5}.normal{color:#475467;background:#edf0f5}</style>
